class Solution:
    def delNodes(self, root: Optional[TreeNode], to_delete: list[int]) -> list[TreeNode]:
        to_del = set(to_delete)
        res = []

        def dfs(node, is_root):
            if not node:
                return None
            deleted = node.val in to_del
            if is_root and not deleted:
                res.append(node)
            node.left = dfs(node.left, deleted)
            node.right = dfs(node.right, deleted)
            return None if deleted else node

        dfs(root, True)
        return res

class Solution {
public:
    vector<TreeNode*> delNodes(TreeNode* root, vector<int>& to_delete) {
        unordered_set<int> to_del(to_delete.begin(), to_delete.end());
        vector<TreeNode*> res;

        auto dfs = [&](auto& self, TreeNode* node, bool is_root) -> TreeNode* {
            if (!node) return nullptr;
            bool deleted = to_del.count(node->val);
            if (is_root && !deleted) {
                res.push_back(node);
            }
            node->left = self(self, node->left, deleted);
            node->right = self(self, node->right, deleted);
            return deleted ? nullptr : node;
        };

        dfs(dfs, root, true);
        return res;
    }
};

import java.util.*;

class Solution {
    Set<Integer> toDel;
    List<TreeNode> res;

    TreeNode dfs(TreeNode node, boolean isRoot) {
        if (node == null) return null;
        boolean deleted = toDel.contains(node.val);
        if (isRoot && !deleted) {
            res.add(node);
        }
        node.left = dfs(node.left, deleted);
        node.right = dfs(node.right, deleted);
        return deleted ? null : node;
    }

    public List<TreeNode> delNodes(TreeNode root, int[] to_delete) {
        toDel = new HashSet<>();
        for (int v : to_delete) toDel.add(v);
        res = new ArrayList<>();
        dfs(root, true);
        return res;
    }
}

